create table if not exists public.discord_recruitment_creators(discord_user_id text not null,role_id text not null,synced_at timestamptz not null default now(),primary key(discord_user_id,role_id));
alter table public.discord_recruitment_creators enable row level security;
drop policy if exists "Users can check their own recruitment creator roles" on public.discord_recruitment_creators;
create policy "Users can check their own recruitment creator roles" on public.discord_recruitment_creators for select to authenticated using(discord_user_id=(select coalesce(raw_user_meta_data->>'provider_id',raw_user_meta_data->>'sub') from auth.users where id=auth.uid()));
grant select on public.discord_recruitment_creators to authenticated;grant select,insert,update,delete on public.discord_recruitment_creators to service_role;
create table if not exists public.recruitment_opportunities(id bigint generated by default as identity primary key,title text not null check(char_length(title) between 1 and 160),opens_at timestamptz not null,closes_at timestamptz not null check(closes_at>opens_at),prerequisites text not null check(char_length(prerequisites) between 30 and 1000),description text not null check(char_length(description) between 500 and 1000),questions jsonb not null check(jsonb_typeof(questions)='array' and jsonb_array_length(questions) between 1 and 8),creator_name text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.recruitment_applications(id uuid primary key default gen_random_uuid(),opportunity_id bigint not null references public.recruitment_opportunities(id) on delete cascade,applicant_id uuid not null references auth.users(id) on delete cascade,applicant_name text not null,answers jsonb not null check(jsonb_typeof(answers)='object'),status text not null default 'Submitted' check(status in('Submitted','Under review','Accepted','Rejected')),submitted_at timestamptz not null default now(),unique(opportunity_id,applicant_id));
alter table public.recruitment_opportunities enable row level security;alter table public.recruitment_applications enable row level security;
create or replace function public.lcfms_can_manage_recruitment() returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.discord_recruitment_creators c join auth.users u on u.id=auth.uid() where c.discord_user_id=coalesce(u.raw_user_meta_data->>'provider_id',u.raw_user_meta_data->>'sub')); $$;
grant execute on function public.lcfms_can_manage_recruitment() to authenticated;
drop policy if exists "Approved members read recruitment opportunities" on public.recruitment_opportunities;create policy "Approved members read recruitment opportunities" on public.recruitment_opportunities for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.access_status='approved'));
drop policy if exists "Discord role members create recruitment opportunities" on public.recruitment_opportunities;create policy "Discord role members create recruitment opportunities" on public.recruitment_opportunities for insert to authenticated with check(created_by=auth.uid() and public.lcfms_can_manage_recruitment());
drop policy if exists "Discord role members update recruitment opportunities" on public.recruitment_opportunities;create policy "Discord role members update recruitment opportunities" on public.recruitment_opportunities for update to authenticated using(public.lcfms_can_manage_recruitment()) with check(public.lcfms_can_manage_recruitment());
drop policy if exists "Discord role members delete recruitment opportunities" on public.recruitment_opportunities;create policy "Discord role members delete recruitment opportunities" on public.recruitment_opportunities for delete to authenticated using(public.lcfms_can_manage_recruitment());
drop policy if exists "Approved members submit applications while open" on public.recruitment_applications;create policy "Approved members submit applications while open" on public.recruitment_applications for insert to authenticated with check(applicant_id=auth.uid() and exists(select 1 from public.profiles p where p.id=auth.uid() and p.access_status='approved') and exists(select 1 from public.recruitment_opportunities o where o.id=opportunity_id and now() between o.opens_at and o.closes_at));
drop policy if exists "Applicants and recruitment creators read applications" on public.recruitment_applications;create policy "Applicants and recruitment creators read applications" on public.recruitment_applications for select to authenticated using(applicant_id=auth.uid() or public.lcfms_can_manage_recruitment());
drop policy if exists "Recruitment creators update application status" on public.recruitment_applications;create policy "Recruitment creators update application status" on public.recruitment_applications for update to authenticated using(public.lcfms_can_manage_recruitment()) with check(public.lcfms_can_manage_recruitment());
grant select,insert,update,delete on public.recruitment_opportunities to authenticated;grant usage,select on sequence public.recruitment_opportunities_id_seq to authenticated;grant select,insert,update on public.recruitment_applications to authenticated;
